#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int x, y;
} Op;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *a = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);

    int maxPos = 0, minPos = 0;
    for (int i = 1; i < N; i++) {
        if (a[i] > a[maxPos]) maxPos = i;
        if (a[i] < a[minPos]) minPos = i;
    }

    Op *ops = (Op *)malloc(sizeof(Op) * (2 * N + 5));
    int cnt = 0;

    if (a[maxPos] >= -a[minPos]) {
        // Make all numbers nonnegative using the maximum element,
        // then propagate left to right.
        for (int i = 0; i < N; i++) {
            if (a[i] < 0) {
                ops[cnt++] = (Op){maxPos + 1, i + 1};
                a[i] += a[maxPos];
            }
        }
        for (int i = 0; i < N - 1; i++) {
            ops[cnt++] = (Op){i + 1, i + 2};
            a[i + 1] += a[i];
        }
    } else {
        // Make all numbers nonpositive using the minimum element,
        // then propagate right to left.
        for (int i = 0; i < N; i++) {
            if (a[i] > 0) {
                ops[cnt++] = (Op){minPos + 1, i + 1};
                a[i] += a[minPos];
            }
        }
        for (int i = N - 1; i >= 1; i--) {
            ops[cnt++] = (Op){i + 1, i};
            a[i - 1] += a[i];
        }
    }

    printf("%d\n", cnt);
    for (int i = 0; i < cnt; i++) {
        printf("%d %d\n", ops[i].x, ops[i].y);
    }

    free(a);
    free(ops);
    return 0;
}

