int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> a(N + 1);
    for (int i = 1; i <= N; i++) cin >> a[i];

    int mx = 1, mn = 1;
    for (int i = 1; i <= N; i++) {
        if (a[i] > a[mx]) mx = i;
        if (a[i] < a[mn]) mn = i;
    }

    vector<pair<int,int>> ops;

    // If all nonnegative, sweep left to right.
    if (a[mn] >= 0) {
        for (int i = 1; i < N; i++) {
            ops.push_back({i, i + 1});
            a[i + 1] += a[i];
        }
    }
    // If all nonpositive, sweep right to left.
    else if (a[mx] <= 0) {
        for (int i = N; i >= 2; i--) {
            ops.push_back({i, i - 1});
            a[i - 1] += a[i];
        }
    }
    // Mixed signs: use the element with larger absolute value.
    else if (a[mx] >= -a[mn]) {
        // Add maximum to all negative elements, making all nonnegative.
        for (int i = 1; i <= N; i++) {
            if (a[i] < 0) {
                ops.push_back({mx, i});
                a[i] += a[mx];
            }
        }
        // Then sweep left to right.
        for (int i = 1; i < N; i++) {
            ops.push_back({i, i + 1});
            a[i + 1] += a[i];
        }
    } else {
        // Add minimum to all positive elements, making all nonpositive.
        for (int i = 1; i <= N; i++) {
            if (a[i] > 0) {
                ops.push_back({mn, i});
                a[i] += a[mn];
            }
        }
        // Then sweep right to left.
        for (int i = N; i >= 2; i--) {
            ops.push_back({i, i - 1});
            a[i - 1] += a[i];
        }
    }

    cout << ops.size() << '\n';
    for (auto [x, y] : ops) {
        cout << x << ' ' << y << '\n';
    }
    return 0;
}

