import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Op {
        int x, y;
        Op(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] a = new long[N];
        int maxIdx = 0, minIdx = 0;
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextLong();
            if (a[i] > a[maxIdx]) maxIdx = i;
            if (a[i] < a[minIdx]) minIdx = i;
        }

        List<Op> ops = new ArrayList<>();

        if (a[maxIdx] >= -a[minIdx]) {
            // Use the maximum positive (or least negative if all negative but still larger in abs comparison)
            // Add it to all elements, then sweep left to right.
            for (int i = 0; i < N; i++) {
                if (i == maxIdx) continue;
                ops.add(new Op(maxIdx + 1, i + 1));
                a[i] += a[maxIdx];
            }
            for (int i = 0; i < N - 1; i++) {
                ops.add(new Op(i + 1, i + 2));
                a[i + 1] += a[i];
            }
        } else {
            // Use the minimum negative
            // Add it to all elements, then sweep right to left.
            for (int i = 0; i < N; i++) {
                if (i == minIdx) continue;
                ops.add(new Op(minIdx + 1, i + 1));
                a[i] += a[minIdx];
            }
            for (int i = N - 1; i >= 1; i--) {
                ops.add(new Op(i + 1, i));
                a[i - 1] += a[i];
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(ops.size()).append('\n');
        for (Op op : ops) {
            sb.append(op.x).append(' ').append(op.y).append('\n');
        }
        System.out.print(sb.toString());
    }
}

