def main():
    input = sys.stdin.readline
    N = int(input())
    a = list(map(int, input().split()))

    mx = max(a)
    mn = min(a)
    imx = a.index(mx)
    imn = a.index(mn)

    ops = []

    # If all numbers are already nonnegative, sweep left -> right
    if mn >= 0:
        for i in range(N - 1):
            ops.append((i + 1, i + 2))
    # If all numbers are already nonpositive, sweep right -> left
    elif mx <= 0:
        for i in range(N - 1, 0, -1):
            ops.append((i + 1, i))
    else:
        # Mixed signs: use the element with larger absolute value as pivot
        if abs(mx) >= abs(mn):
            # Make everything nonnegative by adding max element
            for i in range(N):
                if a[i] < 0:
                    ops.append((imx + 1, i + 1))
                    a[i] += mx
            # Then sweep left -> right
            for i in range(N - 1):
                ops.append((i + 1, i + 2))
        else:
            # Make everything nonpositive by adding min element
            for i in range(N):
                if a[i] > 0:
                    ops.append((imn + 1, i + 1))
                    a[i] += mn
            # Then sweep right -> left
            for i in range(N - 1, 0, -1):
                ops.append((i + 1, i))

    print(len(ops))
